+
+// bfe.u32 d, a, pos, 16, for pos < 32: bits beyond the top of a read as zero
+__device__ __forceinline__ uint32_t exl3_bfe_u32_16(uint32_t a, uint32_t pos)
+{
+    return (a >> pos) & 0xffffu;
