+        #pragma unroll
+        for (int m = 0; m < TILEBLOCKS_M; ++m)
+        {
+            const half* a_ptr = sh1_a_ptr + m * 16 * SH_A_STRIDE + sub_k * 16;
+            rdna_wmma::load_matrix_a(frag_a[buf][m], a_ptr, SH_A_STRIDE);
+        }
