+    auto write_sum_gl = [&] ()
+    {
+        #pragma unroll
+        for (int m = 0; m < TILEBLOCKS_M; ++m)
+        {
+            int row = m * 16 + c_row;
+            if (row >= size_m) continue;
+            #pragma unroll
+            for (int n = 0; n < FRAGS_N_PER_WARP; ++n)
