+template <int bits, int cb, int M>
+__device__ __forceinline__ void exl3_gemv_dot_tile_direct_mr
+(
+    const half* __restrict__ A,
+    const int lda,
+    const uint16_t* __restrict__ B,
+    const int n_tiles,
+    const int tile_n,
+    const int lane,
+    const int kb_begin,
+    const int kb_end,
+    float* out,
+    const int rows_valid = M
+)
