+                (kernel_name<bits_val, false, codebook, warps>), \
+                dim3(num_blocks), dim3(warps * 32), shared_mem_size, stream, \
+                gemv_input, B_ptr, C_ptr, size_k, size_n, lds_core); \
+        }
